import sys, struct

def read_varint(data, pos):
    result = 0
    shift = 0
    while True:
        if pos >= len(data):
            raise EOFError("unexpected end of varint")
        b = data[pos]
        pos += 1
        result |= (b & 0x7F) << shift
        if not (b & 0x80):
            break
        shift += 7
        if shift > 70:
            raise ValueError("varint too long")
    return result, pos

def parse(data, path="", max_depth=64, indent=0):
    pos = 0
    end = len(data)
    while pos < end:
        tag, pos = read_varint(data, pos)
        field = tag >> 3
        wire = tag & 7
        if field == 0:
            print("  "*indent + f"INVALID field 0 at {pos-1}")
            break
        if wire == 0:
            val, pos = read_varint(data, pos)
            printable = val
            print("  "*indent + f"{path}#{field} varint = {printable}")
        elif wire == 1:
            if pos + 8 > end: break
            val = struct.unpack_from("<Q", data, pos)[0]
            pos += 8
            print("  "*indent + f"{path}#{field} fixed64 = {val}")
        elif wire == 2:
            ln, pos = read_varint(data, pos)
            if pos + ln > end: break
            chunk = data[pos:pos+ln]
            pos += ln
            if 0 < ln <= 128 and all(32 <= b < 127 for b in chunk):
                print("  "*indent + f"{path}#{field} len={ln} str = {chunk.decode('ascii', 'replace')}")
            elif ln <= 64:
                print("  "*indent + f"{path}#{field} len={ln} bytes = {chunk.hex()}")
                if max_depth > 0 and ln > 0:
                    try:
                        parse(chunk, f"{path}{field}.", max_depth-1, indent+1)
                    except Exception as e:
                        print("  "*indent + f"    (inner parse failed: {e})")
            elif ln > 64:
                print("  "*indent + f"{path}#{field} len={ln} bytes (truncated) = {chunk[:32].hex()}...")
                if max_depth > 0 and ln > 0:
                    try:
                        parse(chunk, f"{path}{field}.", max_depth-1, indent+1)
                    except Exception:
                        pass
        elif wire == 5:
            if pos + 4 > end: break
            val = struct.unpack_from("<I", data, pos)[0]
            pos += 4
            print("  "*indent + f"{path}#{field} fixed32 = {val}")
        else:
            print("  "*indent + f"{path}#{field} UNKNOWN wiretype {wire}")
            break

if __name__ == "__main__":
    fn = sys.argv[1]
    with open(fn, "rb") as f:
        data = f.read()
    parse(data, max_depth=int(sys.argv[2]) if len(sys.argv) > 2 else 64)

