import struct

def read_varint(data, pos):
    result = 0
    shift = 0
    while True:
        b = data[pos]; pos += 1
        result |= (b & 0x7F) << shift
        if not (b & 0x80): break
        shift += 7
    return result, pos

def parse_fields(data):
    pos = 0
    fields = []
    while pos < len(data):
        tag, pos = read_varint(data, pos)
        field = tag >> 3; wire = tag & 7
        if wire == 0:
            v, pos = read_varint(data, pos); fields.append((field, wire, None, v))
        elif wire == 2:
            ln, pos = read_varint(data, pos)
            b = data[pos:pos+ln]; pos += ln
            fields.append((field, wire, b, None))
    return fields

if __name__ == "__main__":
    import sys
    for fn in sys.argv[1:]:
        with open(fn, "rb") as f:
            data = f.read()
        print(fn, len(data))
        for fld in parse_fields(data):
            f, w, b, v = fld
            if w == 0:
                print(f"  field {f} varint={v}")
            elif b is not None:
                print(f"  field {f} bytes len={len(b)}")

