import sys, dnfile

def list_types(path, keys=None):
    pe = dnfile.dnPE(path)
    out = []
    if pe is None or not hasattr(pe, "net") or pe.net is None or not pe.net.mdtables:
        print(f"{path}: no metadata ({type(pe)})")
        return []
    td = pe.net.mdtables.TypeDef
    if not td:
        return []
    for trow in td:
        ns = str(trow.TypeNamespace)
        nm = str(trow.TypeName)
        nn = (ns + "." + nm) if ns else nm
        out.append((nn, trow))
    return out

for path in sys.argv[1:]:
    types = list_types(path)
    print("=====", path, "types:", len(types))
    if len(types) > 80:
        for (nn, _) in types:
            if any(k in nn for k in ["Archive", "FUSt", "GameArchive", "GurGs", "Persistent", "Achieve", "Record", "BED", "BGW_"]):
                print("  ", nn)
    else:
        for (nn, _) in types:
            print("  ", nn)

