                string mn = mr.GetString(m.Name);
                if (!mn.Contains("ArchiveData") && !mn.Contains("Encrypt")) continue;
                string flags = (m.Attributes & MethodAttributes.Static) != 0 ? "static" : "instance";
                string vis = (m.Attributes & MethodAttributes.Public) != 0 ? "public" : (m.Attributes & MethodAttributes.Family) != 0 ? "protected" : "private/internal";
                var gps = new List<string>();
                foreach (GenericParameterHandle gph in m.GetGenericParameters())
                {
                    GenericParameter gp = mr.GetGenericParameter(gph);
                    gps.Add(mr.GetString(gp.Name));
                }
                Console.WriteLine($"  {vis} {flags} {(gps.Count > 0 ? "<" + string.Join(",", gps) + "> " : "")}{mn}");
            }
        }
        return 0;
    }
}

