using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using Google.Protobuf;
using ArchiveB1;
using b1;

internal static class Program
{
    private static int Main(string[] args)
    {
        string savePath = args.Length > 0 ? args[0] : null;
        if (savePath == null || !File.Exists(savePath))
        {
            Console.Error.WriteLine("usage: SaveDump <save.sav> [maxdepth]");
            return 2;
        }
        int maxDepth = args.Length > 1 ? int.Parse(args[1]) : 12;
        try
        {
            byte[] bytes = File.ReadAllBytes(savePath);
            ArchiveFile info = new ArchiveFile();
            info.MergeFrom(bytes);
            Console.WriteLine("ArchiveFile OK. GameArchivesDataBytes len=" +
                              info.GameArchivesDataBytes.Length);
            byte[] contentBytes = info.GameArchivesDataBytes.ToByteArray();
            FUStBEDArchivesData data =
                BGW_GameArchiveMgr.DeserializeArchiveDataFromBytes<FUStBEDArchivesData>(true, contentBytes);
            Console.WriteLine("Deserialized OK.");
            Dump(data, "", 0, maxDepth, new HashSet<string>());
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine("EXCEPTION: " + ex);
            return 1;
        }
        return 0;
    }

    private static void Dump(object obj, string prefix, int depth, int maxDepth, HashSet<string> seenRef)
    {
        if (obj == null || depth > maxDepth) return;
        Type t = obj.GetType();
        if (IsPrimitive(t))
        {
            Console.WriteLine($"{prefix}{t.Name}: {obj}");
            return;
        }
        if (obj is string s)
        {
            Console.WriteLine($"{prefix}string: {s}");
            return;
        }
        if (obj is ByteString bs)
        {
            Console.WriteLine($"{prefix}ByteString: {bs.Length} bytes");
            return;
        }
        if (obj is IEnumerable && !(obj is IMessage))
        {
            int i = 0;
            foreach (object item in (IEnumerable)obj)
            {
                Dump(item, $"{prefix}[{i}] ", depth + 1, maxDepth, seenRef);
                i++;
                if (i > 200) { Console.WriteLine($"{prefix}... (truncated list)"); break; }
            }
            if (i == 0) Console.WriteLine($"{prefix}(empty enumeration {t.Name})");
            return;
        }
        if (typeof(IMessage).IsAssignableFrom(t))
        {
            Console.WriteLine($"{prefix}{t.FullName}");
        }
        PropertyInfo[] props = t.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly);
        if (props.Length == 0 && !obj.GetType().IsAssignableTo(typeof(IMessage)))
        {
            Console.WriteLine($"{prefix}= {obj}");
            return;
        }
        foreach (PropertyInfo p in props)
        {
            if (p.GetIndexParameters().Length > 0) continue;
            if (p.Name == "Parser" || p.Name == "Descriptor" || p.Name == "FieldsByNumber") continue;
            object val;
            try
            {
                val = p.GetValue(obj);
            }
            catch
            {
                continue;
            }
            if (val == null) continue;
            Type pt = p.PropertyType;
            if (pt == typeof(string) || pt.IsPrimitive || pt.IsEnum ||
                pt == typeof(ByteString) || pt == typeof(double) || pt == typeof(float) ||
                pt == typeof(decimal) || pt == typeof(Guid) || pt == typeof(long) || pt == typeof(ulong))
            {
                Console.WriteLine($"{prefix}{t.Name}.{p.Name} = {val}");
            }
            else
            {
                Dump(val, $"{prefix}{p.Name}.", depth + 1, maxDepth, seenRef);
            }
        }
    }

    private static bool IsPrimitive(Type t)
    {
        return t.IsPrimitive || t.IsEnum || t == typeof(decimal) ||
               t == typeof(double) || t == typeof(float) || t == typeof(Guid);
    }
}

