        Console.WriteLine($"    {mark} {name}  ({reqType}  需求数:{a.Config.RequirementCount})");
        if (a.CompleteRequirementList.Count > 0)
        {
            Console.WriteLine($"       已计数需求: {string.Join(", ", a.CompleteRequirementList)}");
        }
    }

    if (internalAch.Count > 0)
    {
        Console.WriteLine();
        Console.WriteLine($"  内部追踪成就: {internalAch.Count} 个");
    }
}

