                sb.AppendFormat("<div class=\"st\">达成率<div><b>{0}%</b></div></div></div>\n", steamPct);
                sb.AppendLine("<div style=\"margin-top:14px\" class=\"bar\"><span style=\"width:" + steamPct + "%\"></span></div>");
